/* UserMapper.findByEmailAndStatus */
SELECT 
FROM `user`
WHERE email = #{email} AND status = #{status}

/* UserMapper.findByEmail */
SELECT 
FROM `user`
WHERE email = #{email}
LIMIT 1

/* UserMapper.findUsersPaged */
SELECT 
FROM `user`


        AND (email LIKE CONCAT('%',#{keyword},'%') OR nickname LIKE CONCAT('%',#{keyword},'%'))


        AND role_code = #{roleCode}


        AND status = #{status}


ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

/* UserMapper.countUsersPaged */
SELECT COUNT(*)
FROM `user`


        AND (email LIKE CONCAT('%',#{keyword},'%') OR nickname LIKE CONCAT('%',#{keyword},'%'))


        AND role_code = #{roleCode}


        AND status = #{status}

