/* UserMapper.insertUser */
INSERT INTO `user` (email, password, nickname, role_code, tc_id, stdt_id, status, last_login_at, created_by, updated_by, created_at, updated_at)
VALUES (#{email}, #{password}, #{nickname}, #{roleCode}, #{tcId}, #{stdtId}, #{status}, #{lastLoginAt}, #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt})
